//! The C interface C++ calls (`include/rust/ee_rust.h`, generated by cbindgen): GEOpenFormats' two conversions and
//! GESurface::LoadPNG's decode. Bytes given to C++ are `EeOfBytes`, freed with `ee_of_bytes_free`; the resolver asks
//! C++ for a glTF's external buffers.

use std::ffi::c_void;

use crate::{gltf_to_cem, png_to_picture, png_to_sst, Failure};

/// A byte buffer owned by Rust; free it with `ee_of_bytes_free`.
#[repr(C)]
pub struct EeOfBytes {
    pub ptr: *mut u8,
    pub len: usize,
}

impl EeOfBytes {
    fn from_vec(bytes: Vec<u8>) -> EeOfBytes {
        let len = bytes.len();
        EeOfBytes { ptr: Box::into_raw(bytes.into_boxed_slice()) as *mut u8, len }
    }

    fn empty() -> EeOfBytes {
        EeOfBytes { ptr: std::ptr::null_mut(), len: 0 }
    }
}

/// A byte buffer the caller owns (one PNG frame).
#[repr(C)]
pub struct EeOfSlice {
    pub ptr: *const u8,
    pub len: usize,
}

/// Reads an external file a glTF names (`uri`, its bytes, percent-decoded; relative to the .gltf). On success stores
/// the bytes in `*out` with `ee_of_bytes_copy` and returns true; false when it cannot be found. `user` is the
/// `resolve_user` given to `ee_of_gltf_to_cem`.
pub type EeOfResolve =
    Option<unsafe extern "C" fn(user: *mut c_void, uri: *const u8, uri_len: usize, out: *mut EeOfBytes) -> bool>;

unsafe fn slice<'a>(ptr: *const u8, len: usize) -> &'a [u8] {
    if len == 0 {
        &[]
    } else {
        // SAFETY: the caller passes a valid buffer of `len` bytes (each function's contract)
        unsafe { std::slice::from_raw_parts(ptr, len) }
    }
}

fn put_error(err: *mut EeOfBytes, f: Failure) {
    if !err.is_null() {
        // SAFETY: the function's contract: `err` is valid when not null
        unsafe { *err = EeOfBytes::from_vec(f.0) };
    }
}

/// Copies `len` bytes into a Rust-owned buffer (a resolver's answer).
///
/// # Safety
/// `data` is valid for `len` bytes.
#[no_mangle]
pub unsafe extern "C" fn ee_of_bytes_copy(data: *const u8, len: usize) -> EeOfBytes {
    // SAFETY: the function's contract
    EeOfBytes::from_vec(unsafe { slice(data, len) }.to_vec())
}

/// Frees a buffer returned by this interface.
///
/// # Safety
/// `bytes` came from this interface and is not used again.
#[no_mangle]
pub unsafe extern "C" fn ee_of_bytes_free(bytes: EeOfBytes) {
    if !bytes.ptr.is_null() {
        // SAFETY: the buffer came from `EeOfBytes::from_vec`, a boxed slice of exactly `len` bytes
        drop(unsafe { Box::from_raw(std::ptr::slice_from_raw_parts_mut(bytes.ptr, bytes.len)) });
    }
}

/// `GEOpenFormats::GltfToCem`: a .gltf or .glb -> the .cem bytes in `*out`, or false with the message in `*err`.
///
/// # Safety
/// `data` is valid for `len` bytes, `out` and `err` for writing; `resolve`, if any, follows `EeOfResolve`'s contract.
#[no_mangle]
pub unsafe extern "C" fn ee_of_gltf_to_cem(
    data: *const u8,
    len: usize,
    resolve: EeOfResolve,
    resolve_user: *mut c_void,
    out: *mut EeOfBytes,
    err: *mut EeOfBytes,
) -> bool {
    // SAFETY: the function's contract
    unsafe {
        *out = EeOfBytes::empty();
        *err = EeOfBytes::empty();
    }
    let mut fetch = |uri: &[u8]| -> Option<Vec<u8>> {
        let f = resolve?;
        let mut answer = EeOfBytes::empty();
        // SAFETY: the callback's contract; `answer` receives a buffer from ee_of_bytes_copy
        if !unsafe { f(resolve_user, uri.as_ptr(), uri.len(), &mut answer) } {
            return None;
        }
        // SAFETY: the buffer came from ee_of_bytes_copy (or is the empty one)
        let bytes = unsafe { slice(answer.ptr, answer.len) }.to_vec();
        // SAFETY: as above, freed once
        unsafe { ee_of_bytes_free(answer) };
        Some(bytes)
    };
    // SAFETY: the function's contract
    let input = unsafe { slice(data, len) };
    let result = gltf_to_cem(input, if resolve.is_some() { Some(&mut fetch) } else { None });
    match result {
        Ok(bytes) => {
            // SAFETY: the function's contract
            unsafe { *out = EeOfBytes::from_vec(bytes) };
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// `GEOpenFormats::PngToSst`: PNG frames -> the .sst bytes in `*out`, or false with the message in `*err`.
///
/// # Safety
/// `frames` is valid for `count` slices, each slice for its bytes; `out` and `err` for writing.
#[no_mangle]
pub unsafe extern "C" fn ee_of_png_to_sst(
    frames: *const EeOfSlice,
    count: usize,
    out: *mut EeOfBytes,
    err: *mut EeOfBytes,
) -> bool {
    // SAFETY: the function's contract
    unsafe {
        *out = EeOfBytes::empty();
        *err = EeOfBytes::empty();
    }
    // SAFETY: the function's contract
    let frames: Vec<&[u8]> = (0..count).map(|i| unsafe { slice((*frames.add(i)).ptr, (*frames.add(i)).len) }).collect();
    match png_to_sst(&frames) {
        Ok(bytes) => {
            // SAFETY: the function's contract
            unsafe { *out = EeOfBytes::from_vec(bytes) };
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// A decoded picture (`png_to_picture`): `width` x `height` pixels, top row first, B, G, R, A each; `depth` 24 or 32
/// (whether the PNG has alpha). `bgra` is freed with `ee_of_bytes_free`.
#[repr(C)]
pub struct EeOfPicture {
    pub width: u32,
    pub height: u32,
    pub depth: u32,
    pub bgra: EeOfBytes,
}

/// `GESurface::LoadPNG`: a PNG file -> its pixels in `*out`, or false with the message in `*err`.
///
/// # Safety
/// `data` is valid for `len` bytes, `out` and `err` for writing.
#[no_mangle]
pub unsafe extern "C" fn ee_of_png_to_picture(
    data: *const u8,
    len: usize,
    out: *mut EeOfPicture,
    err: *mut EeOfBytes,
) -> bool {
    // SAFETY: the function's contract
    unsafe {
        *out = EeOfPicture { width: 0, height: 0, depth: 0, bgra: EeOfBytes::empty() };
        *err = EeOfBytes::empty();
    }
    // SAFETY: the function's contract
    match png_to_picture(unsafe { slice(data, len) }) {
        Ok(p) => {
            // SAFETY: the function's contract
            unsafe {
                *out =
                    EeOfPicture { width: p.width, height: p.height, depth: p.depth, bgra: EeOfBytes::from_vec(p.bgra) }
            };
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    unsafe fn take(b: &mut EeOfBytes) -> Vec<u8> {
        let v = unsafe { slice(b.ptr, b.len) }.to_vec();
        unsafe { ee_of_bytes_free(std::mem::replace(b, EeOfBytes::empty())) };
        v
    }

    #[test]
    fn the_c_interface_round_trip() {
        unsafe {
            let mut out = EeOfBytes::empty();
            let mut err = EeOfBytes::empty();
            let doc = b"not gltf";
            assert!(!ee_of_gltf_to_cem(doc.as_ptr(), doc.len(), None, std::ptr::null_mut(), &mut out, &mut err));
            assert_eq!(take(&mut err), b"not a glTF 2.0 file".to_vec());

            let frames = [EeOfSlice { ptr: doc.as_ptr(), len: doc.len() }];
            assert!(!ee_of_png_to_sst(frames.as_ptr(), 1, &mut out, &mut err));
            assert_eq!(take(&mut err), b"not a PNG file".to_vec());
        }
    }

    #[test]
    fn the_resolver_callback_answers_external_buffers() {
        unsafe extern "C" fn resolver(user: *mut c_void, uri: *const u8, uri_len: usize, out: *mut EeOfBytes) -> bool {
            unsafe {
                *(user as *mut Vec<u8>) = slice(uri, uri_len).to_vec();
                *out = ee_of_bytes_copy([1u8, 2, 3].as_ptr(), 3);
            }
            true
        }
        let doc = br#"{"buffers":[{"byteLength":3,"uri":"a.bin"}]}"#;
        let mut asked: Vec<u8> = Vec::new();
        unsafe {
            let mut out = EeOfBytes::empty();
            let mut err = EeOfBytes::empty();
            let ok = ee_of_gltf_to_cem(
                doc.as_ptr(),
                doc.len(),
                Some(resolver),
                &mut asked as *mut Vec<u8> as *mut c_void,
                &mut out,
                &mut err,
            );
            assert!(!ok); // no node with a mesh: only the resolving is under test
            assert_eq!(asked, b"a.bin".to_vec());
            assert_eq!(take(&mut err), b"no node with a mesh".to_vec());
        }
    }

    #[test]
    fn bytes_copy_and_free_handle_empty() {
        unsafe {
            let b = ee_of_bytes_copy(std::ptr::null(), 0);
            assert_eq!(b.len, 0);
            ee_of_bytes_free(b);
        }
    }

    #[test]
    fn the_picture_interface_decodes_and_refuses() {
        // a 1x1 RGB PNG (stored zlib block), written here
        let png: [u8; 72] = [
            0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44, 0x52, 0x00, 0x00,
            0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x02, 0x00, 0x00, 0x00, 0x90, 0x77, 0x53, 0xde, 0x00, 0x00, 0x00,
            0x0f, 0x49, 0x44, 0x41, 0x54, 0x78, 0x01, 0x01, 0x04, 0x00, 0xfb, 0xff, 0x00, 0x0a, 0x14, 0x1e, 0x00, 0x68,
            0x00, 0x3d, 0xe8, 0x0c, 0xbb, 0x83, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82,
        ];
        unsafe {
            let mut pic = EeOfPicture { width: 9, height: 9, depth: 9, bgra: EeOfBytes::empty() };
            let mut err = EeOfBytes::empty();
            assert!(ee_of_png_to_picture(png.as_ptr(), png.len(), &mut pic, &mut err));
            assert_eq!((pic.width, pic.height, pic.depth), (1, 1, 24));
            assert_eq!(take(&mut pic.bgra), vec![30, 20, 10, 255]);
            assert!(!ee_of_png_to_picture(b"x".as_ptr(), 1, &mut pic, &mut err));
            assert_eq!((pic.width, pic.bgra.len), (0, 0));
            assert_eq!(take(&mut err), b"not a PNG file".to_vec());
        }
    }
}
